  variantSummary(variant: VariantDraft): string | null { const result = this.store.data().results?.items.find((item) => item.resultId === variant.sourceResultId); if (!result) return null; const provenance = result.provenance; return `Result ${result.resultId} · components ${provenance.components.map((component) => `${component.componentId} ${component.componentVersion} config ${component.configurationRevision}`).join(', ')} · model ${provenance.model.modelId} ${provenance.model.modelVersion} · deployment ${provenance.deploymentRevision} · prompt ${provenance.reproducibility.promptRevision} · policy ${provenance.reproducibility.policyRevision}`; }
  candidateBindingSummary(): string | null { const experiment = this.candidateExperiment(); const result = this.store.data().results?.items.find((item) => item.resultId === this.candidateResultIds()[0]); const evaluator = experiment ? this.evaluatorsFor(experiment).find((item) => `${item.evaluatorId}@${item.evaluatorVersion}` === this.candidateEvaluatorKey()) : null; if (!result || !evaluator || !this.metric()) return null; const definition = this.store.data().evaluators?.items.find((item) => item.evaluatorId === evaluator.evaluatorId && item.evaluatorVersion === evaluator.evaluatorVersion); return `Results ${this.candidateResultIds().join(', ')} · evaluator ${evaluator.evaluatorId} ${evaluator.evaluatorVersion} · metric ${definition?.metric ?? this.metric()} · threshold ${this.thresholdValue()} score · source ${result.createdAt} · reproducibility ${result.provenance.reproducibility.fixtureRevision}/${result.provenance.reproducibility.promptRevision}/${result.provenance.reproducibility.policyRevision}`; }
  createExperiment(event: Event): void { event.preventDefault(); const suite = this.selectedSuite(); if (!suite || !suite.limits || !this.canCreateExperiment()) return; const sourceResults = this.variants().map((item) => this.store.data().results?.items.find((result) => result.resultId === item.sourceResultId)); if (sourceResults.some((result) => !result)) return; const variants = this.variants().map((draft, index) => this.variantFromResult(draft.variantId, sourceResults[index] as EvaluationResult)); const provenance = suite.provenance; const request: CreateEvaluationExperimentRequest = { experimentId: this.experimentId(), experimentVersion: this.experimentVersion(), suite: { id: suite.suiteId, version: suite.suiteVersion }, variants, cohorts: [{ cohortId: this.cohortId(), caseIds: this.selectedCaseIds() }], captureAuthorization: { captureClassification: 'metadata_only', authorizationPurpose: 'synthetic_benchmark', authorizationContext: 'controlled_evaluation', retentionMode: 'manual_only' }, limits: suite.limits, retentionMode: suite.retentionMode, provenance, createdAt: now() }; void this.store.createExperiment(request); }
  createCandidate(event: Event): void { event.preventDefault(); const experiment = this.candidateExperiment(); if (!experiment) return; const suite = this.store.data().suites?.items.find((item) => item.suiteId === experiment.suite.resourceId && item.suiteVersion === experiment.suite.resourceVersion); const evaluator = this.evaluatorsFor(experiment).find((item) => `${item.evaluatorId}@${item.evaluatorVersion}` === this.candidateEvaluatorKey()); const results = this.store.data().results?.items.filter((item) => this.candidateResultIds().includes(item.resultId)) ?? []; if (!suite || !evaluator || !results.length || !this.candidateCohortIds().length) return; const reproduction = results[0].provenance.reproducibility; const sourceResultFrom = results.reduce((value, item) => item.createdAt < value ? item.createdAt : value, results[0].createdAt); const sourceResultTo = results.reduce((value, item) => item.completedAt && item.completedAt > value ? item.completedAt : value, results[0].completedAt ?? results[0].createdAt); const threshold = this.threshold(evaluator); const request: CreateEvaluationBaselineCandidateRequest = { baselineId: uuid(), baselineVersion: '1.0.0', experiment: { id: experiment.experimentId, version: experiment.experimentVersion }, suite: { id: suite.suiteId, version: suite.suiteVersion }, variantId: this.candidateVariantId(), cohortIds: this.candidateCohortIds(), sourceResultIds: this.candidateResultIds(), sourceResultFrom, sourceResultTo, thresholds: [threshold], captureClassification: experiment.captureClassification, reproducibility: reproduction, retentionMode: experiment.retentionMode, provenance: experiment.provenance, createdAt: now() }; void this.store.createBaselineCandidate(request); }
  selectComparisonBaseline(key: string): void { this.comparisonBaselineKey.set(key); this.comparisonVariantId.set(''); this.comparisonCohortIds.set([]); this.comparisonResultIds.set([]); const baseline = this.comparisonBaseline(); if (baseline) this.comparisonCohortIds.set([...baseline.cohortIds]); }
