  openPromotion(item: EvaluationBaseline): void { this.promotionInvoker = document.activeElement instanceof HTMLElement ? document.activeElement : null; this.promotionTarget.set(item); this.promotionConfirmation.set(''); this.promotionAmbiguous.set(false); setTimeout(() => this.promotionTitle?.nativeElement.focus(), 0); }
